import pandas as pd


def run(inputs: dict) -> dict:
    target_snapshot = inputs["target_snapshot"].copy()
    cdc_events = inputs["cdc_events"].copy()
    watermark = inputs["watermark"].copy()

    # Determine the watermark high_ts (take first/only value).
    if len(watermark) > 0:
        high_ts = watermark["high_ts"].iloc[0]
    else:
        high_ts = None

    # Only unapplied events are candidates for sequential application.
    if high_ts is not None:
        events = cdc_events[cdc_events["event_ts"] > high_ts].copy()
    else:
        events = cdc_events.copy()

    # Deterministic sequential order: event_ts then event_seq ascending.
    events = events.sort_values(by=["event_ts", "event_seq"], kind="mergesort")

    # Build initial state from target_snapshot.
    state = {}
    item_dtype = target_snapshot["item_id"].dtype if "item_id" in target_snapshot.columns else None
    qty_dtype = target_snapshot["qty_on_hand"].dtype if "qty_on_hand" in target_snapshot.columns else None
    ts_dtype = target_snapshot["last_event_ts"].dtype if "last_event_ts" in target_snapshot.columns else None

    for row in target_snapshot.itertuples(index=False):
        item_id = row.item_id
        qty_on_hand = row.qty_on_hand
        last_event_ts = row.last_event_ts
        state[item_id] = {
            "qty": qty_on_hand,
            "ts": last_event_ts,
            "exists": True,
        }

    # Apply events sequentially per item in (event_ts, event_seq) order.
    for row in events.itertuples(index=False):
        item_id = row.item_id
        op = row.op
        qty = row.qty
        ts = row.event_ts

        if item_id not in state:
            state[item_id] = {"qty": 0, "ts": None, "exists": False}

        entry = state[item_id]

        if op == "R":
            if not entry["exists"]:
                entry["qty"] = 0
            entry["qty"] = entry["qty"] + qty
            entry["exists"] = True
        elif op == "A":
            entry["qty"] = qty
            entry["exists"] = True
        elif op == "D":
            entry["exists"] = False

        entry["ts"] = ts

    # Build output from items that currently exist.
    out_rows = []
    for item_id, entry in state.items():
        if entry["exists"]:
            out_rows.append(
                {
                    "item_id": item_id,
                    "qty_on_hand": entry["qty"],
                    "last_event_ts": entry["ts"],
                }
            )

    new_snapshot = pd.DataFrame(out_rows, columns=["item_id", "qty_on_hand", "last_event_ts"])

    # Attempt to preserve original dtypes where possible.
    if item_dtype is not None and len(new_snapshot) > 0:
        try:
            new_snapshot["item_id"] = new_snapshot["item_id"].astype(item_dtype)
        except Exception:
            pass
    if qty_dtype is not None and len(new_snapshot) > 0:
        try:
            new_snapshot["qty_on_hand"] = new_snapshot["qty_on_hand"].astype(qty_dtype)
        except Exception:
            pass
    if ts_dtype is not None and len(new_snapshot) > 0:
        try:
            new_snapshot["last_event_ts"] = new_snapshot["last_event_ts"].astype(ts_dtype)
        except Exception:
            pass

    return {"new_snapshot": new_snapshot}
